def cone_names(propdir, root):
    """The set of node names in Cone(root): root + everything transitively contained in root's backing
    file (its sub-nodes, recursively). Raises FaithfulError if `root` isn't a node."""
    occs, children, _ = _containment(propdir)
    if root not in occs:
        raise FaithfulError(f"no node '{root}' in {os.path.relpath(propdir, BOOK_ROOT)}")
    return set(_bottom_up(occs, children, {root}))


def subtree_order(propdir, root):
    """Cone(root) in bottom-up order, with each node's occurrences SCOPED TO THE CONE: a shared helper's
    SP is checked only at call sites whose container file is INSIDE this cone (root's backing file or a
    descendant's), NOT at its uses in other steps. So `--subtree step27` checks `positions@step27` but
    not `positions@step9`. Returns `[(name, [in-cone occurrences]) …]`; P (once per name) is unaffected
    (same single backing file regardless of cone). Raises if `root` isn't a node."""
    occs, children, _ = _containment(propdir)
    if root not in occs:
        raise FaithfulError(f"no node '{root}' in {os.path.relpath(propdir, BOOK_ROOT)}")
    names = _bottom_up(occs, children, {root})
    # An occurrence is IN THE CONE iff its container file is the backing file of some cone node (root's
    # backing file or a descendant's) — that's where all sub-node call sites live. The ROOT node itself
    # is wired at ITS OWN call site (e.g. step27 in Main), so root keeps all its occurrences. This is
    # what scopes a shared helper to this cone: `positions@step27` (container step27.lean ∈ cone) is
    # checked; `positions@step9` (container step9.lean ∉ cone) is not.
    cone_files = {os.path.realpath(backing_file(propdir, n)) for n in names if backing_file(propdir, n)}
    out = []
    for name in names:
        if name == root:
            scoped = occs[name]                       # root: checked at its own call site(s)
        else:
            scoped = [nd for nd in occs[name] if os.path.realpath(nd.file) in cone_files]
        out.append((name, scoped))
    return out


# ── low-level scanners (mirror scripts/check_steps.py) ──────────────────────────────────────────────
def _skip_string(src, i, n):
    """`src[i]` is the opening `"` — return the index just past the closing quote."""
    i += 1
    while i < n and src[i] != '"':
        i += 2 if src[i] == "\\" else 1
    return i + 1


def balanced_paren(src, start):
    """`start` is the index just AFTER an already-open `(` (depth 1). Return the index of its matching
    `)` (the close), skipping nested parens + string literals."""
    depth, i, n = 1, start, len(src)
    while i < n:
        c = src[i]
        if c == '"':
            i = _skip_string(src, i, n); continue
        if c == "(":
            depth += 1
        elif c == ")":
            depth -= 1
            if depth == 0:
                return i
        i += 1
    raise FaithfulError("unbalanced parentheses while scanning")

def _containment(propdir):
    """Return (occs, children, book): the node occurrences, and `children[name]` = the sub-node NAMES
    defined inside name's backing file (the backing-file containment relation). Keyed by NAME, so a
    shared helper's single backing file is visited ONCE even though the name has many occurrences."""
    occs = parse_occurrences(propdir)
    book = book_num(propdir)
    children = {}
    for name in occs:
        bf = backing_file(propdir, name)
        kids = [k.name for k in parse_nodes_in_file(bf, book)] if bf else []
        children[name] = [k for k in kids if k in occs]
    return occs, children, book


def _bottom_up(occs, children, roots):
    """Topological (post-order) bottom-up walk over `children` from `roots`: a node whose backing file
    contains sub-nodes comes AFTER all of those sub-nodes, so the FIRST failure in a sweep is always the
    DEEPEST broken node. Returns the REACHABLE node NAMES in bottom-up order (each once). Deterministic
    via natural_key. Raises on a cyclic containment."""
    ordered, seen = [], set()
    def visit(name, stack):
        if name in seen:
            return
        if name in stack:
            raise FaithfulError(f"cyclic backing-file dependency through '{name}'")
        for kid in children.get(name, []):
            visit(kid, stack | {name})
        seen.add(name)
        ordered.append(name)
    for name in sorted(roots, key=natural_key):

    if main_mod.endswith(".Main"):
        try:                                                      # Book2.Prop05.Main -> Book2/Prop05
            propdir = fl.propdir_of(main_mod[:-len(".Main")].replace(".", os.sep))
        except fl.FaithfulError:
            propdir = None                                        # no folder on disk → construction arm only
    mod_prefix = fl.prop_prefix(propdir) if propdir else None     # e.g. "Book2.Prop05"
    # locator → node name (authoritative map from the parsed `have`/sentence tree, not a name guess).
    try:
        occ = fl.parse_occurrences(propdir) if propdir else {}
    except fl.FaithfulError:
        occ = {}
    node_by_loc = {nd.loc: nm for nm, nds in occ.items() for nd in nds
                   if nd.kind == "sentence" and nd.loc is not None}
    try:                                                          # @suppress_deps_check waivers (loc → reason)
        suppressed = fl.suppressed_dep_locs(propdir) if propdir else {}
    except fl.FaithfulError as e:
        suppressed = {}
        group_rc |= report("every @suppress_deps_check tag is well-formed", False, [str(e)])
    construction = applied_by_mod.get(main_mod, [])               # whole-Main `as` constructions
    dep_lines, waived, n_cites = [], [], 0
    for s in sents:
        if s.get('kind') == 'structural':
            continue                                              # intro/conclude/wts: background citations, not proof steps
        if s['loc'] in suppressed:                                # criterion-3 waived (documented reason)
            waived.append(f"{s['loc']}: {suppressed[s['loc']]}")
            continue
        for cbook, num in CITE.findall(s['text']):
            n_cites += 1
            if any(name_matches(ap['name'], cbook, num) for ap in construction):
                continue                                          # construction arm
            # proof arm: search the citing sentence's cone modules (if it has a node + we found the dir).
            cone_hit = False
            node = node_by_loc.get(s['loc'])
            if node is not None and propdir is not None:
                try:
                    cone = fl.cone_names(propdir, node)
                except fl.FaithfulError:
                    cone = set()
                cone_mods = {f"{mod_prefix}.{n}" for n in cone}
                cone_hit = any(name_matches(ap['name'], cbook, num)
                               for m in cone_mods for ap in applied_by_mod.get(m, []))
                if not cone_hit and cone:
                    # Fallback: check transitive deps of Main-applied helpers whose name
                    # corresponds to a cone node. Catches direct term-level proposition calls
                    # inside a helper (not via euclid_apply) — the prop appears in the
                    # propClosure deps attached to the Main apply entry, not in the step module's
                    # applied_by_mod, so the direct check above misses it.
                    pfx = f"helper_{book}_{prop}_"
                    for ap in applied_by_mod.get(main_mod, []):
                        local = ap['name'].rsplit('.', 1)[-1] if '.' in ap['name'] else ap['name']
                        if local.startswith(pfx) and local[len(pfx):] in cone:
                            if any(name_matches(dep, cbook, num) for dep in ap.get('deps', [])):
                                cone_hit = True
                                break
            if cone_hit:
                continue
            where = f"its helper cone (node `{node}`)" if node else \
                    "any helper cone (structural sentence — must be a Main construction)"
            dep_lines.append(f"{s['loc']} ({s['ref']}) cites [Prop.~{cbook}.{num}] but no "
                             f"`proposition_{num}` of Book {cbook} is applied `… as …` in {main_mod} "
                             f"(construction) nor inside {where}")
    ok_lines = dep_lines or [f"all {n_cites} citation(s) resolve to the cited book+number"]
    if waived:
        ok_lines = ok_lines + [f"{len(waived)} sentence(s) waived by @suppress_deps_check:"] \
                   + [f"    {w}" for w in waived]
    group_rc |= report("every cited [Prop.~B.M] is referenced in the prop (book-aware: Main construction or sentence's cone)",
                 not dep_lines, ok_lines)

    canon_rel, canon_path = canon_path_for(book, prop)
    ok1, lines1 = criterion1_exact(sents, canon_rel, canon_path)
    group_rc |= report("all sentences present + concatenation reproduces the original text exactly",
                 ok1, lines1)

